public class BankAccount
{
    public decimal Balance { get; private set; }

    public void Deposit(decimal amount)
    {
        if (amount <= 0)
            throw new ArgumentException("Positive amounts only");
        Balance += amount;
    }
}

Why is the setter of Balance private?

class Counter
{
    public static int Total;
    public int Mine;

    public void Click() { Total++; Mine++; }
}

var a = new Counter();
var b = new Counter();
a.Click();
b.Click();

What are Counter.Total and a.Mine?
